21: package fx
22: 
23: import (
24: 	"fmt"
25: 
26: 	"go.uber.org/dig"
27: 	"go.uber.org/fx/fxevent"
28: 	"go.uber.org/fx/internal/fxreflect"
29: 	"go.uber.org/multierr"
30: )
31: 
32: // A container represents a set of constructors to provide
33: // dependencies, and a set of functions to invoke once all the
34: // dependencies have been initialized.
35: //
36: // This definition corresponds to the dig.Container and dig.Scope.
37: type container interface {
38: 	Invoke(any, ...dig.InvokeOption) error
39: 	Provide(any, ...dig.ProvideOption) error
40: 	Decorate(any, ...dig.DecorateOption) error
41: }
42: 
43: // Module is a named group of zero or more fx.Options.
44: //
45: // A Module scopes the effect of certain operations to within the module.
46: // For more information, see [Decorate], [Replace], or [Invoke].
47: //
48: // Module allows packages to bundle sophisticated functionality into easy-to-use
49: // logical units.
50: // For example, a logging package might export a simple option like this:
51: //
52: //	package logging
53: //
54: //	var Module = fx.Module("logging",
55: //		fx.Provide(func() *log.Logger {
56: //			return log.New(os.Stdout, "", 0)
57: //		}),
58: //		// ...
59: //	)
60: //
61: // A shared all-in-one microservice package could use Module to bundle
62: // all required components of a microservice:
63: //
64: //	package server
65: //
66: //	var Module = fx.Module("server",
67: //		logging.Module,
68: //		metrics.Module,
69: //		tracing.Module,
70: //		rpc.Module,
71: //	)
72: //
73: // When new global functionality is added to the service ecosystem,
74: // it can be added to the shared module with minimal churn for users.
75: //
76: // Use the all-in-one pattern sparingly.
77: // It limits the flexibility available to the application.
78: func Module(name string, opts ...Option) Option {
79: 	mo := moduleOption{
80: 		name:     name,
81: 		location: fxreflect.CallerStack(1, 2)[0],
82: 		options:  opts,
83: 	}
84: 	return mo
85: }
86: 
87: type moduleOption struct {
88: 	name     string
89: 	location fxreflect.Frame
90: 	options  []Option
91: }
92: 
93: func (o moduleOption) String() string {
94: 	return fmt.Sprintf("fx.Module(%q, %v)", o.name, o.options)
95: }
96: 
97: func (o moduleOption) apply(mod *module) {
98: 	// This get called on any submodules' that are declared
99: 	// as part of another module.
100: 
101: 	// 1. Create a new module with the parent being the specified
102: 	// module.
103: 	// 2. Apply child Options on the new module.
104: 	// 3. Append it to the parent module.
105: 
106: 	// Create trace as parent's trace with this module's location pre-pended.
107: 	trace := append([]string{fmt.Sprintf("%v (%v)", o.location, o.name)}, mod.trace...)
108: 	newModule := &module{
109: 		name:   o.name,
110: 		parent: mod,
111: 		trace:  trace,
112: 		app:    mod.app,
113: 	}
114: 	for _, opt := range o.options {
115: 		opt.apply(newModule)
116: 	}
117: 	mod.modules = append(mod.modules, newModule)
118: }
119: 
120: type module struct {
121: 	parent         *module
122: 	name           string
123: 	trace          []string
124: 	scope          scope
125: 	provides       []provide
126: 	invokes        []invoke
127: 	decorators     []decorator
128: 	modules        []*module
129: 	app            *App
130: 	log            fxevent.Logger
131: 	fallbackLogger fxevent.Logger
132: 	logConstructor *provide
133: }
134: 
135: // scope is a private wrapper interface for dig.Container and dig.Scope.
136: // We can consider moving this into Fx using type constraints after Go 1.20
137: // is released and 1.17 is deprecated.
138: type scope interface {
139: 	Decorate(f any, opts ...dig.DecorateOption) error
140: 	Invoke(f any, opts ...dig.InvokeOption) error
141: 	Provide(f any, opts ...dig.ProvideOption) error
142: 	Scope(name string, opts ...dig.ScopeOption) *dig.Scope
143: 	String() string
144: }
145: 
146: // builds the Scopes using the App's Container. Note that this happens
147: // after applyModules' are called because the App's Container needs to
148: // be built for any Scopes to be initialized, and applys' should be called
149: // before the Container can get initialized.
150: func (m *module) build(app *App, root *dig.Container) {
151: 	if m.parent == nil {
152: 		m.scope = root
153: 	} else {
154: 		parentScope := m.parent.scope
155: 		m.scope = parentScope.Scope(m.name)
156: 		// use parent module's logger by default
157: 		m.log = m.parent.log
158: 	}
159: 
160: 	if m.logConstructor != nil {
161: 		// Since user supplied a custom logger, use a buffered logger
162: 		// to hold all messages until user supplied logger is
163: 		// instantiated. Then we flush those messages after fully
164: 		// constructing the custom logger.
165: 		m.fallbackLogger, m.log = m.log, new(logBuffer)
166: 	}
167: 
168: 	for _, mod := range m.modules {
169: 		mod.build(app, root)
170: 	}
171: }
172: 
173: func (m *module) provideAll() {
174: 	for _, p := range m.provides {
175: 		m.provide(p)
176: 	}
177: 
178: 	for _, m := range m.modules {
179: 		m.provideAll()
180: 	}
181: }
182: 
183: func (m *module) provide(p provide) {
184: 	if m.app.err != nil {
185: 		return
186: 	}
187: 
188: 	if p.IsSupply {
189: 		m.supply(p)
190: 		return
191: 	}
192: 
193: 	funcName := fxreflect.FuncName(p.Target)
194: 	var info dig.ProvideInfo
195: 	opts := []dig.ProvideOption{
196: 		dig.FillProvideInfo(&info),
197: 		dig.Export(!p.Private),
198: 		dig.WithProviderBeforeCallback(func(bci dig.BeforeCallbackInfo) {
199: 			m.log.LogEvent(&fxevent.BeforeRun{
200: 				Name:       funcName,
201: 				Kind:       "provide",
202: 				ModuleName: m.name,
203: 			})
204: 		}),
205: 		dig.WithProviderCallback(func(ci dig.CallbackInfo) {
206: 			m.log.LogEvent(&fxevent.Run{
207: 				Name:       funcName,
208: 				Kind:       "provide",
209: 				ModuleName: m.name,
210: 				Runtime:    ci.Runtime,
211: 				Err:        ci.Error,
212: 			})
213: 		}),
214: 	}
215: 
216: 	if err := runProvide(m.scope, p, opts...); err != nil {
217: 		m.app.err = err
218: 	}
219: 	outputNames := make([]string, len(info.Outputs))
220: 	for i, o := range info.Outputs {
221: 		outputNames[i] = o.String()
222: 	}
223: 
224: 	m.log.LogEvent(&fxevent.Provided{
225: 		ConstructorName: funcName,
226: 		StackTrace:      p.Stack.Strings(),
227: 		ModuleTrace:     append([]string{p.Stack[0].String()}, m.trace...),
228: 		ModuleName:      m.name,
229: 		OutputTypeNames: outputNames,
230: 		Err:             m.app.err,
231: 		Private:         p.Private,
232: 	})
233: }
234: 
235: func (m *module) supply(p provide) {
236: 	typeName := p.SupplyType.String()
237: 	opts := []dig.ProvideOption{
238: 		dig.Export(!p.Private),
239: 		dig.WithProviderBeforeCallback(func(bci dig.BeforeCallbackInfo) {
240: 			m.log.LogEvent(&fxevent.BeforeRun{
241: 				Name:       fmt.Sprintf("stub(%v)", typeName),
242: 				Kind:       "supply",
243: 				ModuleName: m.name,
244: 			})
245: 		}),
246: 		dig.WithProviderCallback(func(ci dig.CallbackInfo) {
