27: // Shutdowner provides a method that can manually trigger the shutdown of the
28: // application by sending a signal to all open Done channels. Shutdowner works
29: // on applications using Run as well as Start, Done, and Stop. The Shutdowner is
30: // provided to all Fx applications.
31: type Shutdowner interface {
32: 	Shutdown(...ShutdownOption) error
33: }
34: 
35: // ShutdownOption provides a way to configure properties of the shutdown
36: // process. Currently, no options have been implemented.
37: type ShutdownOption interface {
38: 	apply(*shutdowner)
39: }
40: 
41: type exitCodeOption int
42: 
43: func (code exitCodeOption) apply(s *shutdowner) {
44: 	s.exitCode = int(code)
45: }
46: 
47: var _ ShutdownOption = exitCodeOption(0)
48: 
49: // ExitCode is a [ShutdownOption] that may be passed to the Shutdown method of the
50: // [Shutdowner] interface.
51: // The given integer exit code will be broadcasted to any receiver waiting
52: // on a [ShutdownSignal] from the [Wait] method.
53: func ExitCode(code int) ShutdownOption {
54: 	return exitCodeOption(code)
55: }
56: 
57: type shutdownTimeoutOption time.Duration
58: 
59: func (shutdownTimeoutOption) apply(*shutdowner) {}
60: 
61: var _ ShutdownOption = shutdownTimeoutOption(0)
62: 
63: // ShutdownTimeout is a [ShutdownOption] that allows users to specify a timeout
64: // for a given call to Shutdown method of the [Shutdowner] interface. As the
65: // Shutdown method will block while waiting for a signal receiver relay
66: // goroutine to stop.
67: //
68: // Deprecated: This option has no effect. Shutdown is not a blocking operation.
69: func ShutdownTimeout(timeout time.Duration) ShutdownOption {
