78: // Shutdown broadcasts a signal to all of the application's Done channels
79: // and begins the Stop process. Applications can be shut down only after they
80: // have finished starting up.
81: func (s *shutdowner) Shutdown(opts ...ShutdownOption) error {
82: 	for _, opt := range opts {
83: 		opt.apply(s)
