package fx

import (
	"go.uber.org/fx/fxevent"
)

// logBuffer will buffer all messages until a logger has been
// initialized.
type logBuffer struct {
	events []fxevent.Event
	logger fxevent.Logger
}

// LogEvent buffers or logs an event.
func (l *logBuffer) LogEvent(event fxevent.Event) {
	if l.logger == nil {
		l.events = append(l.events, event)
	} else {
		l.logger.LogEvent(event)
	}
}

// Connect flushes out all buffered events to a logger and resets them.
func (l *logBuffer) Connect(logger fxevent.Logger) {
	l.logger = logger
	for _, e := range l.events {
		logger.LogEvent(e)
	}
	l.events = nil
}","lineStart":1,"lineEnd":50,"totalLines":50,"truncated":false}},"title":"repos/ruangong-0707/fx/log.go","time":{"start":1783572693379,"end":1783572693385}},"id":"prt_f45377fef001vxM8Bc8JEa4Q5f","sessionID":"ses_0bac951b8ffeuyJFm8hs5DkEPD","messageID":"msg_f453752ca001dmKEKYeGjIjkum"}}

