21: package fx
22: 
23: import (
24: 	"fmt"
25: 	"os"
26: 	"sync"
27: )
28: 
29: // broadcaster broadcasts signals to registered signal listeners.
30: // All methods on the broadcaster are concurrency-safe.
31: type broadcaster struct {
32: 	// This lock is used to protect all fields of broadcaster.
33: 	// Methods on broadcaster should protect all concurrent access
34: 	// by taking this lock when accessing its fields.
35: 	// Conversely, this lock should NOT be taken outside of broadcaster.
36: 	m sync.Mutex
37: 
38: 	// last will contain a pointer to the last ShutdownSignal received, or
39: 	// nil if none, if a new channel is created by Wait or Done, this last
40: 	// signal will be immediately written to, this allows Wait or Done state
41: 	// to be read after application stop
42: 	last *ShutdownSignal
43: 
44: 	// contains channels created by Done
45: 	done []chan os.Signal
46: 
47: 	// contains channels created by Wait
48: 	wait []chan ShutdownSignal
49: }
50: 
51: func (b *broadcaster) reset() {
52: 	b.m.Lock()
53: 	defer b.m.Unlock()
54: 	b.last = nil
55: }
56: 
57: // Done creates a new channel that will receive signals being broadcast
58: // via the broadcaster.
59: //
60: // If a signal has been received prior to the call of Done,
61: // the signal will be sent to the new channel.
62: func (b *broadcaster) Done() <-chan os.Signal {
63: 	b.m.Lock()
64: 	defer b.m.Unlock()
65: 
66: 	ch := make(chan os.Signal, 1)
67: 	// If we had received a signal prior to the call of done, send it's
68: 	// os.Signal to the new channel.
69: 	// However we still want to have the operating system notify signals to this
70: 	// channel should the application receive another.
71: 	if b.last != nil {
72: 		ch <- b.last.Signal
73: 	}
74: 	b.done = append(b.done, ch)
75: 	return ch
76: }
77: 
78: // Wait creates a new channel that will receive signals being broadcast
79: // via the broadcaster.
80: //
81: // If a signal has been received prior to the call of Wait,
82: // the signal will be sent to the new channel.
83: func (b *broadcaster) Wait() <-chan ShutdownSignal {
84: 	b.m.Lock()
85: 	defer b.m.Unlock()
86: 
87: 	ch := make(chan ShutdownSignal, 1)
88: 
89: 	if b.last != nil {
90: 		ch <- *b.last
91: 	}
92: 
93: 	b.wait = append(b.wait, ch)
94: 	return ch
95: }
96: 
97: // Broadcast sends the given signal to all channels that have been created
98: // via Done or Wait. It does not block on sending, and returns an unsentSignalError
99: // if any send did not go through.
100: func (b *broadcaster) Broadcast(signal ShutdownSignal) error {
101: 	b.m.Lock()
102: 	defer b.m.Unlock()
103: 
104: 	b.last = &signal
105: 
106: 	channels, unsent := b.broadcast(
107: 		signal,
108: 		b.broadcastDone,
109: 		b.broadcastWait,
110: 	)
111: 
112: 	if unsent != 0 {
113: 		return &unsentSignalError{
114: 			Signal: signal,
115: 			Total:  channels,
116: 			Unsent: unsent,
117: 		}
118: 	}
119: 
120: 	return nil
121: }
122: 
123: func (b *broadcaster) broadcast(
124: 	signal ShutdownSignal,
125: 	anchors ...func(ShutdownSignal) (int, int),
126: ) (int, int) {
127: 	var channels, unsent int
128: 
129: 	for _, anchor := range anchors {
130: 		c, u := anchor(signal)
131: 		channels += c
132: 		unsent += u
133: 	}
134: 
135: 	return channels, unsent
136: }
137: 
138: func (b *broadcaster) broadcastDone(signal ShutdownSignal) (int, int) {
139: 	var unsent int
140: 
141: 	for _, reader := range b.done {
142: 		select {
143: 		case reader <- signal.Signal:
144: 		default:
145: 			unsent++
146: 		}
147: 	}
148: 
149: 	return len(b.done), unsent
150: }
151: 
152: func (b *broadcaster) broadcastWait(signal ShutdownSignal) (int, int) {
153: 	var unsent int
154: 
155: 	for _, reader := range b.wait {
156: 		select {
157: 		case reader <- signal:
158: 		default:
159: 			unsent++
160: 		}
161: 	}
162: 
163: 	return len(b.wait), unsent
164: }
165: 
166: type unsentSignalError struct {
167: 	Signal ShutdownSignal
168: 	Unsent int
169: 	Total  int
170: }
171: 
172: func (err *unsentSignalError) Error() string {
173: 	return fmt.Sprintf(
174: 		"send %v signal: %v/%v channels are blocked",
175: 		err.Signal,
176: 		err.Unsent,
177: 		err.Total,
